using Kernel = bool (*)(volatile uint32_t*, const uint32_t*, uint32_t*, volatile uint64_t*, volatile bool*);
struct Variant { const char *name; Kernel fn; unsigned w2; unsigned w4; };
static const Variant variants[] = {
    {"actual_repaired", sha256_pipelined_mine_v9, 8, 8},
    {"guard_16", bench_guard_16, 8, 8},
};
static void stress_task(void *) {
    block_header_t h={}; sha256_hash_t mid, hash;
    miner_sha256_midstate(&mid,&h);
    for (;;) {
        for (unsigned i=0;i<2048;++i) { h.nonce++; miner_sha256_header(&mid,&hash,&h); }
        vTaskDelay(1);
    }
}
void v9_benchmark_task(void *) {
    WiFi.mode(WIFI_STA); WiFi.setSleep(false);
    xTaskCreatePinnedToCore(stress_task,"SwStress",8192,NULL,1,NULL,0);
    Serial.println("[KERNEL] BEGIN");
    for (unsigned pass=0; pass<4; ++pass) {
        uint32_t header[20];
        for (unsigned i=0; i<20; ++i) header[i] = 0x12345678u + i*0x9e3779b9u + pass*0x1020304u;
        // Reverse variant order on alternate passes; baseline also runs at the end.
        for (unsigned vi=0; vi<=sizeof(variants)/sizeof(variants[0]); ++vi) {
            unsigned j = vi == sizeof(variants)/sizeof(variants[0]) ? 0 :
                (pass&1 ? sizeof(variants)/sizeof(variants[0])-1-vi : vi);
            const auto &v = variants[j];
            if(WiFi.scanComplete()!=WIFI_SCAN_RUNNING) { WiFi.scanDelete(); WiFi.scanNetworks(true); }
            uint32_t nonce = 0xffff0000u, hits[64];
            volatile uint64_t count=0;
            volatile bool active=false;
            v.fn((volatile uint32_t*)0x3ff03000,header,&nonce,&count,&active);
            nonce=0xffff0000u; count=0; active=true;
            g_v5_delays[1]=v.w2; g_v5_delays[3]=v.w4;
            uint64_t us=0;
            for (unsigned k=0; k<64; ++k) {
                uint32_t before=nonce;
                int64_t t=esp_timer_get_time();
                v.fn((volatile uint32_t*)0x3ff03000,header,&nonce,&count,&active);
                us += esp_timer_get_time()-t;
                hits[k]=nonce;
                if (nonce==before) { Serial.println("[KERNEL] ERROR no progress"); vTaskDelete(NULL); }
                vTaskDelay(1);
            }
            Serial.printf("[KERNEL] RESULT pass=%u variant=%s count=%llu us=%llu start=ffff0000 end=%08x hits=",pass,v.name,count,us,nonce);
            for (unsigned k=0;k<64;++k) Serial.printf("%s%08x",k?",":"",hits[k]);
            Serial.println(); Serial.flush();
            vTaskDelay(10);
        }
    }
    Serial.println("[KERNEL] DONE");
    vTaskDelete(NULL);
}
